function cfg(room=state.room,ch=state.chapter||0){const investigation=book.chapters[ch].investigations[room],w=investigation.world;if(!w)return rooms[room%rooms.length];const image=`assets/${w.imageKey}.webp`,base=rooms.find(r=>r.image===image)||rooms[0],positions=newLayouts[w.imageKey];const floor=positions?[{x:.12,y:.53},{x:.88,y:.53},{x:.93,y:.95},{x:.07,y:.95}]:base.floor;const points=positions?positions.map(([x,y])=>[x,y,Math.max(.2,Math.min(.8,x)),Math.max(.58,Math.min(.86,y+.15))]):base.points;return {...base,...w,image,floor,points};}

function persist(){if(admin.active)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Browseropslag is niet beschikbaar. Exporteer je onderzoeksboek via Instellingen.');}}
function notify(text){clearTimeout(timer);$('#toast').textContent=text;$('#toast').classList.add('visible');$('#announcements').textContent=text;timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function sound(){if(state.muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();[440,554,659].forEach((f,n)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+n*.09;o.frequency.value=f;g.gain.setValueAtTime(.03,t);g.gain.exponentialRampToValueAtTime(.001,t+.4);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.4);});}catch{}}
function toolSprite(t){return `<span class="tool-sprite" style="background-position:${[0,50,100][t.cell%3]}% ${t.cell<3?0:100}%" aria-hidden="true"></span>`;}
function header(){return `<header class="topbar"><button class="brand" data-act="home"><span class="brand-mark">O</span><span><span class="brand-name">Onder de oppervlakte</span><small>Les ${state?.chapter+1||1} · ${esc(course.lessons[state?.chapter||0].title.replace(/\s*\(kort\)/,''))}</small></span></button><nav aria-label="Spelnavigatie"><button class="nav-link" data-act="route">${icon('map')}<span class="nav-label">Route</span></button><button class="nav-link" data-act="knowledge">${icon('book')}<span class="nav-label">Naslag</span></button><button class="nav-link" data-act="settings">${icon('settings')}<span class="nav-label">Bewaren</span></button><button class="nav-link" data-act="adminPrompt">${icon('tool')}<span class="nav-label">Beheer</span></button><div class="level"><div class="level-badge"><span>${level(state)}</span></div><div><strong>Level ${level(state)}</strong><small>${xp(state)} XP · ${state.beats.length} inzichten</small></div></div></nav></header>`;}
function render(){activeSpot=null;activeBeat=null;activeCard=null;goal=null;arrival=null;app.innerHTML=state.started?`<div class="adventure-shell">${header()}${admin.active?adminBar():''}${world()}</div>`:`${header()}${landing()}`;if(state.started){actor=project(actor,cfg().floor);positionActor();}}
function landing(){return `<main class="hero" id="main"><div class="hero-art" style="background-image:url('assets/room-dispatch.webp')" role="img" aria-label="De noodcentrale van NOVA bij zonsondergang"></div><div class="hero-copy"><p class="eyebrow">NOVA · Het tweede leven</p><h1>De stroom<br><em>valt uit.</em></h1><p class="lead">Morgen lanceert NOVA een nieuwe telefoon.<br>Vanavond is er niet genoeg stroom voor iedereen.</p><p class="lead">Verken de kamers. Spreek de mensen.<br>Verzamel gereedschap en ontdek wat er achter de belofte zit.</p><div class="hero-actions">${button((state.beats.length?'Ga verder met je avontuur':'Stap de noodcentrale binnen')+' '+icon('arrow'),'start')}${button('Bekijk de route','route','btn-quiet')}</div><div class="intro-meta"><span>${icon('bag')} Voorwerpen gebruiken</span><span>${icon('talk')} Vragen & doorvragen</span></div></div><div class="hero-foot"><div><p>Les 1 · Economie en systemen</p><p>Onderzoeken → verbanden leggen → eindpuzzel</p></div><div><p class="image-caption">Business Ethics · vijf adventures</p><p>Je onderzoeksboek reist met je mee.</p></div></div></main>`;}
function world(){const c=cfg(),i=inv(),done=i.beats.filter(b=>state.beats.includes(b.id)).length;return `<main class="adventure-main" id="main"><section class="world-side"><div class="world-heading"><div><p class="eyebrow">NOVA · ${state.room+1} / ${chapter().investigations.length} · ${esc(i.title)}</p><h1>${esc(c.name)}</h1></div><span class="room-location">${state.rooms.includes(i.id)?'Verbanden gelegd':`${done} / ${i.beats.length} onderzocht`}</span></div><div class="mission-strip"><p>${esc(i.world?.exit?.problem||i.mission)}</p><div>${button('Mijn opdracht','openBriefing','btn-quiet')}${button('Theorie vooraf','lessonPrimer','btn-quiet')}</div></div><div class="world-viewport"><div class="walk-scene" id="walk-scene" tabindex="0" role="region" aria-label="Bestuur je onderzoeksdrone in ${esc(c.name)} met WASD, pijltjestoetsen of door te klikken"><img class="room-art" src="${c.image}" alt="${esc(c.name)}, een geïllustreerde kamer met onderzoeksvoorwerpen" draggable="false"><div class="room-shade"></div><div class="walk-instructions">Klik om te vliegen · klik op een voorwerp om het te onderzoeken</div><div class="foot-shadow" id="foot-shadow"></div><img id="player" class="actor" src="assets/drone.png" alt="Je onderzoeksdrone" draggable="false">${i.beats.map((b,n)=>{const p=c.points[n%c.points.length],offset=n>=c.points.length?.07:0;return `<button class="room-object ${state.beats.includes(b.id)?'solved':''}" data-act="approach" data-id="${b.id}" style="--spot-x:${p[0]*100}%;left:${p[0]*100}%;top:${(p[1]+offset)*100}%" aria-label="${esc(b.title)}" title="${esc(b.title)}"><span class="object-dot">${state.beats.includes(b.id)?'✓':n+1}</span><span class="object-label">${esc(b.title)}</span></button>`;}).join('')}${toolObject()}${extraObjects()}${npcObject()}${exitObject()}<div class="scene-speech" id="scene-speech"><strong>${esc(npc().name)}</strong><span>${esc(npc().opening)}</span></div></div><div id="tray-mount"></div></div><div class="room-controls"><div class="verb-controls"><button class="verb ${verb==='look'?'active':''}" data-act="verb" data-verb="look">Verkennen</button><button class="verb ${verb==='inspect'?'active':''}" data-act="verb" data-verb="inspect">Inspecteren</button><button class="verb ${verb==='use'?'active':''}" data-act="verb" data-verb="use">Gebruiken</button><button class="verb" data-act="npc">${icon('talk')} Praten</button></div><span>WASD / pijltjes · klik om te vliegen</span><div class="exploration-controls"><button data-act="searchSpots" aria-pressed="false">Toon zoekplekken</button><button data-act="help">Hoe werkt dit?</button></div></div><div class="inventory-bar" aria-label="Je gereedschap"><span class="inventory-title">Mijn<br>gereedschap</span>${state.tools.length?state.tools.map(id=>{const t=tools.find(t=>t.id===id);return `<button class="pocket-item ${selectedTool===id?'active':''}" data-act="selectTool" data-id="${id}" title="${esc(t.detail)}">${toolSprite(t)}<span>${esc(t.name)}</span></button>`;}).join(''):'<span class="empty-pocket">Er ligt gereedschap in de kamer. Kijk goed rond.</span>'}</div></section><aside class="notebook" aria-label="Onderzoeksboek"><p class="eyebrow">Persoonlijk veldboek · automatisch bewaard</p><h2>Mijn aanwijzingen</h2><p class="book-subtitle">${esc(i.title)}<br>Verzamel het bewijs. Maak dan de verbinding.</p><div class="notebook-progress">${i.beats.map(b=>`<span class="${state.beats.includes(b.id)?'done':''}"></span>`).join('')}</div><div class="clue-list">${i.beats.map(b=>`<div class="clue-entry ${state.beats.includes(b.id)?'':'locked'}"><span>${state.beats.includes(b.id)?'✓':'○'}</span><div>${state.beats.includes(b.id)?`<button data-act="readClue" data-id="${b.id}" draggable="true" data-clue="${b.id}">${esc(b.clueTitle||b.title)}</button><small>Gevonden · te gebruiken als bewijs</small>`:`${esc(b.clueTitle||b.title)}<small>Nog te onderzoeken</small>`}</div></div>`).join('')}</div><label class="notes-title" for="field-notes">Mijn voorspellingen & verbanden</label><textarea id="field-notes" data-notes="${i.id}" placeholder="Wat verwacht je? Wat veranderde er? Welke aanwijzingen horen bij elkaar?">${esc(state.notes[i.id]||'')}</textarea><span class="save-indicator" id="save-indicator">Notities blijven op dit apparaat.</span>${button(state.rooms.includes(i.id)?'Verbanden opnieuw bekijken':`Breng de puzzelstukken samen ${icon('arrow')}`,'finale','combine-btn',investigated(state,i)?'':'disabled')}<p class="book-footer">${investigated(state,i)?'Alle aanwijzingen zijn onderzocht.':'Eerst alle aanwijzingen onderzoeken.'}</p>${state.rooms.includes(i.id)?button(lastRoom()?`De eindpuzzel van les ${state.chapter+1}`:'Open de volgende plek','nextRoom','combine-btn'):''}</aside></main>`;}
function toolObject(){const t=tools.find(t=>(state.chapter||0)===0&&t.room===originalRoomIndex()&&!state.tools.includes(t.id));if(!t)return '';const p=cfg().tool;return `<button class="room-object tool-object" data-act="approachTool" data-id="${t.id}" style="--spot-x:${p[0]*100}%;left:${p[0]*100}%;top:${p[1]*100}%"><span class="object-dot">${icon('tool')}</span><span class="object-label">${esc(t.name)}</span></button>`;}
function npcList(){const row=dialogues.rooms.find(r=>r.investigationId===inv().id);return row?.npcs||[row?.npc||{name:'Noor',role:'Onderzoekspartner',opening:inv().beats[0].intro,topics:inv().beats.map(b=>({id:b.id,question:`Wat speelt bij ${b.title.toLowerCase()}?`,answer:b.hint,followups:[{id:'example',question:'Kun je dat verder uitleggen?',answer:b.explainAfter}]}))}];}
function npc(){return npcList().find(n=>n.name===npcFocus)||npcList()[0];}
function inspectPlace(x,y){const c=cfg(),clamped={x:Math.max(0,Math.min(1,x)),y:Math.max(0,Math.min(1,y))},spots=extraSpots(),nearest=spots.map(t=>({t,d:Math.hypot(t.point[0]-clamped.x,t.point[1]-clamped.y)})).sort((a,b)=>a.d-b.d)[0],spot=nearest?.d<.19?nearest.t:null;const title=spot?.title||c.name,caption=spot?.observation||'Bekijk de ruimte van dichtbij. Zoek naar documenten, apparatuur en sporen; wat je aantreft kan een verklaring ondersteunen of juist ontkrachten.';const view=document.createElement('section');view.id='place-inspection';view.className='place-view';view.setAttribute('aria-label','Inspecteer '+title);view.innerHTML=`<div class="place-photo" style="background-image:url('${c.image}');background-position:${clamped.x*100}% ${clamped.y*100}%"></div><div class="place-caption"><p class="eyebrow">Je kijkt van dichtbij</p><h2>${esc(title)}</h2><p>${esc(caption)}</p>${spot?button('Onderzoek dit spoor','inspectSpot','btn-secondary',`data-id="${spot.id}"`):''}${button('Terug naar de kamer','closeInspection','btn-primary')}</div><button class="close" data-act="closeInspection" aria-label="Sluit inspectie">×</button>`;$('.world-viewport').append(view);view.querySelector('.close').focus({preventScroll:true});}
function adminBar(){return `<div class="admin-bar"><strong>Beheerpreview</strong><span>Je gewone voortgang blijft apart.</span>${button('Alle gebieden','adminOverview','btn-quiet')}${button('Inhoud controleren','adminContent','btn-quiet')}${button('Gebiedspuzzel','adminFinal','btn-quiet')}${button('Leseindpuzzel','adminLessonFinal','btn-quiet')}${button('Afsluitende vragen','beginKnowledge','btn-quiet')}<a href="plan.html" target="_blank" rel="noopener">Bouwplan ↗</a>${button('Terug naar mijn spel','adminExit','btn-quiet')}</div>`;}
function adminPrompt(){if(admin.active){adminOverview();return;}openPanel('Beheer van de adventure',`<p>Bekijk gebieden, theorie, gesprekken en puzzels rechtstreeks.</p><label class="notes-title" for="admin-code">Toegangscode</label><input id="admin-code" type="password" autocomplete="off" class="admin-code"><div class="panel-footer">${button('Open beheer','adminLogin')}</div><p id="admin-error" aria-live="polite"></p>`,'Ontwikkeloverzicht');}
function adminLogin(){if($('#admin-code')?.value!=='fabian1'){$('#admin-error').textContent='De code klopt niet.';return;}if(!admin.active){admin.backup=structuredClone(state);admin.active=true;}render();adminOverview();}
function adminOverview(){openPanel('Alle gebieden van de module',`<p>Open een gebied of controleer theorie, gesprekken en puzzels. Deze preview verandert je gewone voortgang niet.</p>${book.chapters.map((ch,n)=>`<section class="admin-chapter"><p class="eyebrow">Les ${n+1}</p><h3>${esc(ch.title)}</h3><div class="room-map">${ch.investigations.map((i,k)=>`<button class="map-room" data-act="adminVisit" data-chapter="${n}" data-index="${k}"><img src="${cfg(k,n).image}" alt=""><div><h3>${esc(cfg(k,n).name)}</h3><p>${i.beats.length} onderzoeksmomenten · ${i.finale.slots.length} puzzelverbanden</p></div></button>`).join('')}</div></section>`).join('')}${campaign.chapters.slice(book.chapters.length).map(ch=>`<div class="lesson-info">${esc(ch.title)} · wordt gebouwd</div>`).join('')}`,'Beheerpreview');}
function adminVisit(b){if(!admin.active)return;state.chapter=Number(b.dataset.chapter);state.room=Number(b.dataset.index);state.started=true;state.tools=tools.map(t=>t.id);actor={x:.5,y:.85};panel.close();render();}
function adminContent(){if(!admin.active)return;const i=inv();openPanel('Inhoud van '+cfg().name,`<p>Controleer hoe broninhoud, wereldbewijs en opdrachten met elkaar samenhangen.</p>${i.beats.map(b=>`<details class="admin-content-item"><summary>${esc(b.title)} · ${esc(b.type)}</summary><p>${esc(b.intro)}</p><p><strong>Begrippen:</strong> ${b.concepts.map(esc).join(' · ')}</p>${(b.reveal||[]).map(x=>`<article><h3>${esc(x.title||x.label)}</h3><p>${esc(x.text)}</p></article>`).join('')}<p><strong>Ondersteuning:</strong> ${esc(b.hint)}</p><p><strong>Uitleg na de handeling:</strong> ${esc(b.explainAfter)}</p><p><strong>Brononderdelen:</strong> ${b.sourceBlocks.map(esc).join(' · ')}</p>${button('Bekijk de interactie','adminBeat','btn-secondary',`data-id="${b.id}"`)}</details>`).join('')}`,'Theorie & uitvoering');}
function adminBeat(b){if(!admin.active)return;const beat=inv().beats.find(x=>x.id===b.dataset.id);if(!beat)return;const needed=requiredTool(beat);if(needed){selectedTool=needed;verb='use';}panel.close();openBeat(beat);}
function adminFinal(){if(!admin.active)return;inv().beats.forEach(b=>collect(state,b));beginFinale();}
function adminLessonFinal(){if(!admin.active)return;chapter().investigations.forEach(i=>{i.beats.forEach(b=>collect(state,b));if(!state.rooms.includes(i.id))state.rooms.push(i.id);});beginFinale(true);}
function adminExit(){if(!admin.active)return;state=admin.backup;admin.active=false;admin.backup=null;panel.close();render();}
function extraSpots(){return (state.chapter||0)===0?extras.rooms.find(r=>r.room===originalRoomIndex())?.spots||[]:inv().world?.spots||[];}
function extraObjects(){return extraSpots().map(x=>`<button class="extra-object ${state.exploration[x.id]?'visited':''}" data-act="approachExtra" data-id="${x.id}" aria-label="Onderzoek ${esc(x.title)}" style="--spot-x:${x.point[0]*100}%;left:${x.point[0]*100}%;top:${x.point[1]*100}%"><span class="extra-dot"></span><span class="extra-label">${esc(x.title)}</span></button>`).join('');}
function approachExtra(id){const x=extraSpots().find(x=>x.id===id);if(!x)return;closeTray();walkTo(...x.approach,()=>{activeSpot=x;renderExtra();});speak(`Ik bekijk ${x.title.toLowerCase()}.`,'Jij');}
function renderExtra(feedback='',answered=false){const x=activeSpot;if(!x)return;const locked=x.requires&&(!state.tools.includes(x.requires)||selectedTool!==x.requires||verb!=='use');state.exploration[x.id]=locked?'locked':'visited';persist();document.querySelector(`[data-act="approachExtra"][data-id="${x.id}"]`)?.classList.add('visited');let body=`<p>${esc(x.observation)}</p>`;if(locked){body+=`<div class="tray-hint">Dit serviceslot past op de servicesleutel. Je kunt later terugkomen met het juiste gereedschap.</div>`;}else{if(x.question&&!answered)body+=`<p>${esc(x.question)}</p><div class="puzzle-cards">${x.options.map((o,n)=>button(esc(o.text),'sideAnswer','puzzle-card',`data-index="${n}"`)).join('')}</div>`;if(x.detail)body+=`<div class="reveal-text"><p>${esc(x.detail)}</p></div>`;if(feedback)body+=`<div class="small-feedback ${answered?'':'retry'}">${esc(feedback)}</div>`;if(!x.question||answered)body+=button(state.tools.includes('camera')?'Leg vast met mijn onderzoekscamera':'Noteer dit zijspoor','saveSide','btn-secondary');}body+=button('Verder zoeken','closeTray','btn-primary');tray(x.title,body,'Een spoor onderzoeken');}
function saveSide(){if(!activeSpot)return;const x=activeSpot,text=x.options?.find(o=>o.correct)?.feedback||x.detail||x.observation,entry=`${x.title}: ${x.observation} ${text}`;if(!(state.notes[inv().id]||'').includes(entry)){state.notes[inv().id]=(state.notes[inv().id]||'')+'\n'+entry;persist();$('#field-notes').value=state.notes[inv().id];}notify('Zijspoor vastgelegd in je onderzoeksboek.');}
function npcPosition(index=0){const positions=[[.34,.76],[.37,.79],[.37,.79],[.31,.63],[.4,.91],[.69,.64]],coords=(state.chapter||0)===0&&index===0?(positions[originalRoomIndex()]||[.32,.8]):index===0?[.32,.8]:[.68,.8];return project({x:coords[0],y:coords[1]},cfg().floor);}
function npcObject(){return npcList().map((n,index)=>{const p=npcPosition(index),cell=['Noor','Omar','Mila','Iris','Eva','Lena'].indexOf(n.name);return `<div class="npc-shadow" style="left:${p.x*100}%;top:${p.y*100}%"></div><button class="world-npc" data-act="approachNPC" data-name="${esc(n.name)}" aria-label="Praat met ${esc(n.name)}" style="left:${p.x*100}%;top:${p.y*100}%;--npc-sole:${cell<3?95:92}%;background-position:${[0,50,100][cell%3]}% ${cell<3?0:100}%"><span class="npc-label">${esc(n.name)} · ${icon('talk')}</span></button>`;}).join('');}
function approachNPC(b){npcFocus=b?.dataset?.name||npcList()[0].name;closeTray();const index=npcList().findIndex(n=>n.name===npcFocus),p=npcPosition(index);walkTo(p.x+.065,p.y+.025,npcPanel);speak(`Ik vlieg naar ${npc().name}.`,'Jij');}
function speak(text,name=npc().name){const box=$('#scene-speech');if(box){box.innerHTML=`<strong>${esc(name)}</strong><span>${esc(text)}</span>`;box.style.display='block';}$('#announcements').textContent=text;}
function positionActor(){const p=$('#player'),shadow=$('#foot-shadow');if(!p)return;p.style.left=actor.x*100+'%';p.style.top=(actor.y-.11)*100+'%';p.style.transform=`translate(-50%,-50%) rotate(${goal?(actor.facing||1)*5:0}deg) scale(${.83+(actor.y-.55)*.6})`;p.style.zIndex=actor.y<npcPosition().y?'2':'4';shadow.style.left=actor.x*100+'%';shadow.style.top=actor.y*100+'%';}
function cancelMovement(){goal=null;arrival=null;$('#player')?.classList.remove('walking');}
function walkTo(x,y,callback=null){goal=project({x,y},cfg().floor);arrival=callback;const p=$('#player');p?.classList.add('walking');}
function approach(bid){const b=inv().beats.find(b=>b.id===bid),n=inv().beats.indexOf(b),p=cfg().points[n%cfg().points.length];if(!b)return;closeTray();walkTo(p[2],p[3],()=>openBeat(b));speak(verb==='use'&&selectedTool?`Ik neem de ${tools.find(t=>t.id===selectedTool)?.name.toLowerCase()} mee naar ${b.title.toLowerCase()}.`:`Ik ga ${b.title.toLowerCase()} onderzoeken.`,'Jij');}
function approachTool(id){const t=tools.find(t=>t.id===id),p=cfg().tool;closeTray();walkTo(p[2],p[3],()=>showTool(t));}
function showTool(t){tray(t.name,`<div class="tool-display">${toolSprite(t)}</div><p>${esc(t.detail)}</p>${button('Neem mee','takeTool','btn-primary',`data-id="${t.id}"`)}`,'Een bruikbaar voorwerp');}
function tray(title,body,kicker='Onderzoeken'){const mount=$('#tray-mount');if(!mount)return;mount.innerHTML=`<section class="interaction-tray" aria-label="${esc(title)}"><header class="tray-head"><div><p class="eyebrow">${esc(kicker)}</p><h2>${esc(title)}</h2></div><button class="close" data-act="closeTray" aria-label="Sluit onderzoek">×</button></header><div class="tray-body">${body}</div></section>`;goal=null;arrival=null;$('#player')?.classList.remove('walking');mount.querySelector('.close').focus({preventScroll:true});}
function closeInspection(){$('#place-inspection')?.remove();}
function closeTray(){closeInspection();const m=$('#tray-mount');if(m)m.innerHTML='';activeBeat=null;activeCard=null;}
function requiredTool(b){if(b.requiresTool)return b.requiresTool;if((state.chapter||0)!==0)return null;if(b.simulation==='electricity')return 'meter';if(inv().id==='m1-03'&&b.type==='connect')return 'map';if(inv().id==='m1-04'&&b.type==='build')return 'key';return null;}
function openBeat(b){const required=requiredTool(b);if(required&&!state.tools.includes(required)){speak(`Hiervoor heb ik de ${tools.find(t=>t.id===required).name.toLowerCase()} nodig. Die vind ik ${(state.chapter||0)>0?'in de eerste les; je kunt daar via Route terugkijken':required==='map'?'bij de routekaart in het vorige depot':'in deze kamer'}.`,'Jij');notify('Zoek het gereedschap en gebruik het bij dit voorwerp.');return;}if(required&&(verb!=='use'||selectedTool!==required)){speak(`Selecteer de ${tools.find(t=>t.id===required).name.toLowerCase()} in je gereedschap en gebruik hem hier.`,'Jij');notify('Klik eerst op het juiste gereedschap en daarna op het voorwerp.');return;}activeBeat=b;activeCard=null;renderBeat();}
function renderBeat(feedback='',passed=false){const b=activeBeat;if(!b)return;const solved=state.beats.includes(b.id)&&!b.replay;let body=`<p>${esc(b.intro)}</p><button class="hint-toggle" data-act="hint">Ik wil een handvat</button><div id="beat-hint"></div>`;
if(solved){body=`<div class="clue-earned"><p class="eyebrow">Bewijs in je onderzoeksboek</p><div class="display">${esc(b.clueTitle||b.title)}</div><p>${esc(b.explainAfter)}</p>${button('Bekijk opnieuw','replayBeat','btn-secondary')}${button('Terug naar de kamer','closeTray')}</div>`;tray(b.title,body,'Aanwijzing gevonden');return;}
if(b.type==='inspect'){const seen=state.seen[b.id]||[];body+=`<div class="inspect-grid">${b.reveal.map((r,n)=>`<button class="inspect-object ${seen.includes(r.id)?'seen':''}" data-act="inspect" data-id="${r.id}"><div class="object-photo" style="background-image:url('${cfg().image}');background-position:${[10,40,70,90][n%4]}% ${[25,60,45,80][n%4]}%"></div><span>${seen.includes(r.id)?'✓ ':''}${esc(r.label)}</span></button>`).join('')}</div><div id="reveal-content"></div>${seen.length===b.reveal.length?button('Bewaar de bevinding','collectBeat'):''}`;}
if(b.type==='sort'){const assignments=state.sorts[b.id]||{};body+=`<p class="puzzle-help">Pak een kaart en leg hem op een plek. Slepen of aanklikken werkt allebei.</p><div class="puzzle-cards">${b.cards.map(c=>`<button class="puzzle-card ${assignments[c.id]?'placed':''} ${activeCard===c.id?'selected':''}" draggable="true" data-card="${c.id}" data-act="selectCard" data-id="${c.id}">${esc(c.text)}</button>`).join('')}</div><div class="drop-zones">${b.categories.map(c=>`<button class="drop-zone" data-drop="${c.id}" data-act="placeCard" data-id="${c.id}"><strong>${esc(c.label)}</strong>${b.cards.filter(p=>assignments[p.id]===c.id).map(p=>`<span class="zone-card">${esc(p.text)}</span>`).join('')}</button>`).join('')}</div>${button('Onderzoek de verbindingen','checkBeat')}`;}
if(b.type==='connect'){const links=state.links[b.id]||{},right=[...b.pairs].sort((a,c)=>a.right.localeCompare(c.right));body+=`<p class="puzzle-help">Kies links een stuk bewijs. Verbind het rechts aan wat erdoor wordt verklaard.</p><div class="board-columns"><div>${b.pairs.map(p=>`<button class="puzzle-card ${activeCard===p.id?'selected':''} ${links[p.id]?'placed':''}" data-act="selectCard" data-id="${p.id}">${esc(p.left)}${links[p.id]?`<br><small>→ ${esc(b.pairs.find(x=>x.id===links[p.id])?.right)}</small>`:''}</button>`).join('')}</div><div>${right.map(p=>`<button class="puzzle-card" data-act="connect" data-id="${p.id}">${esc(p.right)}</button>`).join('')}</div></div>${button('Bekijk of het verband klopt','checkBeat')}`;}
if(b.type==='order'){const order=state.orders[b.id]||[],pool=[...b.order].sort((a,c)=>a.text.localeCompare(c.text));body+=`<p class="puzzle-help">Bouw de keten door kaarten in volgorde toe te voegen. Klik een geplaatste kaart om hem terug te leggen.</p><div class="order-list">${Array.from({length:b.order.length},(_,n)=>`<button class="order-slot" data-act="removeOrder" data-index="${n}" data-orderdrop="${n}"><strong>${n+1}</strong>${order[n]?esc(b.order.find(o=>o.id===order[n])?.text):'Leg hier de volgende stap'}</button>`).join('')}</div><div class="puzzle-cards">${pool.filter(p=>!order.includes(p.id)).map(p=>`<button class="puzzle-card" draggable="true" data-card="${p.id}" data-act="addOrder" data-id="${p.id}">${esc(p.text)}</button>`).join('')}</div>${button('Laat de keten werken','checkBeat')}`;}
if(b.type==='build'){const selected=state.selections[b.id]||[];body+=`<p class="puzzle-help">Kies onderdelen die elkaar aanvullen. Elke ingreep heeft mogelijkheden en grenzen.</p><div class="puzzle-cards">${b.options.map(o=>`<button class="puzzle-card ${selected.includes(o.id)?'selected':''}" data-act="build" data-id="${o.id}">${selected.includes(o.id)?'✓ ':''}${esc(o.text)}</button>`).join('')}</div>${button('Voer mijn ontwerp uit','checkBeat')}`;}
if(b.type==='decision'){body+=`<div class="puzzle-cards">${b.options.map(o=>`<button class="puzzle-card" data-act="decide" data-id="${o.id}">${esc(o.text)}</button>`).join('')}</div>`;}
if(b.type==='experiment')body+=experimentMarkup(b);
if(b.type==='media')body+=mediaMarkup(b);
if(feedback)body+=`<div class="small-feedback ${passed?'':'retry'}" aria-live="polite">${esc(feedback)}</div>`;
if(passed)body+=button('Bewaar de bevinding '+icon('book'),'collectBeat');
tray(b.title,body,b.type==='experiment'?'Experiment · voorspel, verander, verklaar':b.sceneObject==='person'?'Gesprek · onderzoek een afweging':'Een aanwijzing onderzoeken');if(b.type==='experiment')refreshExperiment();}
function inspect(id){const b=activeBeat,r=b.reveal.find(r=>r.id===id);state.seen[b.id]??=[];if(!state.seen[b.id].includes(id))state.seen[b.id].push(id);persist();renderBeat();$('#reveal-content').innerHTML=`<article class="reveal-text"><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></article>`;}
function selectCard(id){activeCard=id;document.querySelectorAll('[data-act=selectCard]').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));}
function placeCard(id){if(!activeCard){notify('Kies eerst een kaart.');return;}const b=activeBeat;state.sorts[b.id]??={};state.sorts[b.id][activeCard]=id;activeCard=null;persist();renderBeat();}
function connect(id){if(!activeCard){notify('Kies eerst het bewijs links.');return;}state.links[activeBeat.id]??={};state.links[activeBeat.id][activeCard]=id;activeCard=null;persist();renderBeat();}
function addOrder(id){const b=activeBeat;state.orders[b.id]??=[];if(!state.orders[b.id].includes(id))state.orders[b.id].push(id);persist();renderBeat();}
function checkBeat(){const b=activeBeat;let pass=false,feedback='';if(b.type==='sort'){const a=state.sorts[b.id]||{},wrong=b.cards.filter(c=>a[c.id]!==c.category);pass=!wrong.length;feedback=pass?b.explainAfter:wrong[0].feedback||b.hint;}if(b.type==='connect'){const a=state.links[b.id]||{},wrong=b.pairs.filter(c=>a[c.id]!==c.id);pass=!wrong.length;feedback=pass?b.explainAfter:wrong[0].feedback||b.hint;}if(b.type==='order'){const a=state.orders[b.id]||[],wrong=b.order.find((c,n)=>a[n]!==c.id);pass=!wrong;feedback=pass?b.explainAfter:wrong.feedback||b.hint;}if(b.type==='build'){const a=state.selections[b.id]||[],required=b.required||b.options.filter(o=>o.correct).map(o=>o.id);pass=a.length===required.length&&required.every(id=>a.includes(id));feedback=pass?b.explainAfter:(b.options.find(o=>a.includes(o.id)&&!required.includes(o.id))?.feedback||'Je ontwerp mist nog een onderdeel. '+b.hint);}renderBeat(feedback,pass);}
function decide(id){const b=activeBeat,o=b.options.find(o=>o.id===id);state.choices[b.id]=id;persist();renderBeat(o.feedback,o.correct);}
function collectBeat(){const b=activeBeat;if(!b)return;const repeat=state.beats.includes(b.id);b.replay=false;collect(state,b);persist();sound();render();tray(b.clueTitle||b.title,`<div class="clue-earned"><p class="eyebrow">${repeat?"Aanwijzing opnieuw onderzocht":"Aanwijzing bewaard · +30 XP"}</p><p>${esc(b.explainAfter)}</p><label class="note-label" for="clue-observation">Wat betekent dit voor jouw onderzoek?</label><textarea id="clue-observation" data-notes="${b.id}" placeholder="Een korte observatie in je eigen woorden.">${esc(state.notes[b.id]||'')}</textarea>${button('Terug naar de kamer','closeTray')}</div>`,'In je onderzoeksboek');if(investigated(state,inv()))speak('We hebben nu alle aanwijzingen. Welke verbanden verklaren samen wat er gebeurt?');}
function experimentMarkup(b){if(!customSimulation(b))return legacyExperimentMarkup(b);const spec=b.simulationSpec,v={...modelDefaults(spec),...state.expValues[b.id]},controls=spec.parameters.map(p=>{const value=v[p.id];if(p.type==='select')return `<label class="model-control"><span>${esc(p.label)}</span><select data-exp="${p.id}">${p.options.map(o=>`<option value="${esc(o.value)}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;if(p.type==='boolean')return `<label class="model-control model-check"><span>${esc(p.label)}</span><input type="checkbox" data-exp="${p.id}" ${value?'checked':''}></label>`;return `<label class="model-control"><span>${esc(p.label)}</span><input type="range" min="${p.min}" max="${p.max}" step="${p.step||1}" value="${value}" data-exp="${p.id}"><strong data-expvalue="${p.id}">${value}</strong></label>`;}).join('');return `<div class="model-terminal ${b.simulation==='claim-boundary'?'claim-model':''}"><p class="model-label">${esc(spec.title)}</p><div class="model-controls">${controls}</div><div id="model-output"></div><div id="model-visual" aria-hidden="true"></div></div><details class="model-assumptions"><summary>Wat dit model meeneemt en wat niet</summary>${spec.assumptions.map(x=>`<p>${esc(x)}</p>`).join('')}</details><label class="note-label" for="prediction">${esc(spec.predictionPrompt||'Wat verwacht je vóór je deze proef uitvoert?')}</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Mijn verwachting en de reden daarvoor…">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Voer deze proef uit','runExperiment')}<div id="experiment-feedback"></div>`;}
function refreshModel(b,v){state.expValues[b.id]=v;persist();document.querySelectorAll('[data-expvalue]').forEach(e=>e.textContent=v[e.dataset.expvalue]);const result=modelOutcome(b.simulation,v),format=n=>typeof n==='number'?n.toLocaleString('nl-NL',{maximumFractionDigits:2}):String(n);$('#model-output').innerHTML=outputRows(b.simulationSpec).map(row=>`<div class="model-readout"><span>${esc(row.label)}</span><strong>${esc(format(result[row.id]))}</strong><small>${esc(row.unit||'')}</small></div>`).join('');const count=b.simulation==='sorter'?12:b.simulation==='incentives'?4:20,filled=b.simulation==='sorter'?result.recoveredItems:b.simulation==='incentives'?result.reached:Math.round(v.coveragePercent/5);$('#model-visual').innerHTML=Array.from({length:count},(_,n)=>`<span class="model-item ${n<filled?'active':''}"></span>`).join('');}
function runModelTrial(){const b=activeBeat,v=expValues(),prediction=state.notes[`${b.id}:prediction`]?.trim();if(!prediction){notify('Noteer eerst je verwachting en waarom.');$('#prediction').focus();return;}state.trials[b.id]??=[];const trials=state.trials[b.id],signature=JSON.stringify(v);if(!trials.some(t=>t.signature===signature))trials.push({signature,values:v,prediction,result:modelOutcome(b.simulation,v)});persist();const ready=modelContrasted(b,trials),spec=b.simulationSpec;$('#experiment-feedback').innerHTML=`<p class="trial-record">${trials.length} verschillende proeven bewaard.</p><details class="trial-log"><summary>Bekijk mijn proeflog</summary>${trials.map((t,n)=>`<article><strong>Proef ${n+1}</strong><p>${spec.parameters.map(p=>`${esc(p.label)}: ${esc(t.values[p.id])}`).join(' · ')}</p><p>${outputRows(spec).map(row=>`${esc(row.label)}: ${Number(t.result[row.id]).toLocaleString('nl-NL',{maximumFractionDigits:2})}`).join(' · ')}</p></article>`).join('')}</details><div class="small-feedback">${ready?'Je hebt relevante verschillen naast elkaar gezet. Verklaar het mechanisme en de grens van het model.':spec.contrastRequirements.map(x=>esc(typeof x==='string'?x.label||x:x.id==='baseline'?'Vergelijk een route zonder bescherming onder hoge targetdruk.':'Vergelijk met een beschermde route en voldoende beoordelingsruimte.')).join(' ')}</div>${ready?`<label class="note-label" for="experiment-interpretation">${esc(spec.interpretationPrompt||'Wat verandert in je gecontroleerde vergelijking, en wat kun je hieruit niet afleiden?')}</label><textarea id="experiment-interpretation" data-notes="${b.id}:interpretation">${esc(state.notes[`${b.id}:interpretation`]||'')}</textarea>${button('Onderbouw mijn vergelijking','finishExperiment')}`:''}`;}
function finishModel(){const b=activeBeat;if(!state.notes[`${b.id}:interpretation`]?.trim()){notify('Leg de vergelijking eerst in je eigen woorden uit.');return;}$('#experiment-feedback').innerHTML=`<p>${esc(b.simulationSpec.conceptQuestion||'Welke conclusie wordt door deze vergelijking ondersteund?')}</p><div class="puzzle-cards">${conceptOptions(b).map(o=>button(esc(o.text),'interpretExperiment','puzzle-card',`data-id="${o.id}"`)).join('')}</div>`;}
function mediaMarkup(b){const seen=(state.seen[b.id]||[]).includes('opened'),note=state.notes[`${b.id}:media`]||'';return `<div class="source-projector"><div class="projector-head"><span>Bronprojectie · ${esc(b.media.title)}</span><span>Onderzoeksbron</span></div><div id="projection-screen"><div class="projection-poster"><span class="projection-play">▶</span><p>${esc(b.media.viewingTask)}</p>${button('Bekijk het bronfragment','projectMedia')}</div></div><p class="source-note">${esc(admin.active?(b.media.contentVerification||'Oorspronkelijk bronmateriaal'):'Gebruik de bron als bewijs: verbind een concreet voorbeeld aan je onderzoek.')}</p></div><label class="note-label" for="media-notes">${esc(b.media.afterPrompt||'Welk begrip helpt het bronvoorbeeld verklaren, en hoe werkt het in deze casus?')}</label><textarea id="media-notes" data-notes="${b.id}:media" placeholder="Leg de bron aan de casus uit. Gebruik een concreet voorbeeld en benoem een grens.">${esc(note)}</textarea>${button('Bewaar mijn bronvergelijking','collectMedia','btn-primary',seen&&note.trim().split(/\s+/).length>=15?'':'disabled')}`;}
function projectMedia(){const b=activeBeat,id=b.media.youtube;if(!/^[A-Za-z0-9_-]{11}$/.test(id))return;state.seen[b.id]=['opened'];persist();$('#projection-screen').innerHTML=`<iframe title="${esc(b.media.title)}" src="https://www.youtube-nocookie.com/embed/${id}?start=${Number(b.media.start)||0}" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a href="https://www.youtube.com/watch?v=${id}&t=${Number(b.media.start)||0}s" target="_blank" rel="noopener">Open de oorspronkelijke video ↗</a>`;refreshMediaGate();}
function refreshMediaGate(){if(activeBeat?.type!=='media')return;const seen=(state.seen[activeBeat.id]||[]).includes('opened'),text=state.notes[`${activeBeat.id}:media`]||'',button=document.querySelector('[data-act=collectMedia]');if(button)button.disabled=!seen||text.trim().split(/\s+/).filter(Boolean).length<15;}
function collectMedia(){const b=activeBeat;if(!(state.seen[b.id]||[]).includes('opened')||(state.notes[`${b.id}:media`]||'').trim().split(/\s+/).filter(Boolean).length<15){notify('Bekijk de bron en leg minstens één concreet verband in je eigen woorden vast.');return;}collectBeat();}
function legacyExperimentMarkup(b){const saved=state.expValues[b.id]||{};if(b.simulation==='electricity'){return `<p class="puzzle-help">Voorspel het gevolg. Verdeel daarna de schaarse stroom en voer je plan uit.</p><div class="experiment-controls">${[['production','Productie',60],['repair','Reparatie',40],['emergency','Noodklanten',40]].map(([id,label,max])=>`<label class="power-channel"><span>${label}</span><input type="range" min="0" max="${max}" step="10" value="${saved[id]??(id==='production'?60:20)}" data-exp="${id}" aria-label="Stroom voor ${label}"><strong data-expvalue="${id}"></strong></label>`).join('')}</div><div class="power-meter" id="power-meter"><i></i></div><p class="puzzle-help" id="capacity-label"></p><div class="consequence-cards" id="consequences"></div><label class="note-label" for="prediction">Wat verwacht je dat deze verdeling verandert?</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Je voorspelling vóór je de verdeling uitvoert.">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Schakel de verdeling in','runExperiment')}<div id="experiment-feedback"></div><p class="experiment-caption">Fictieve situatie · 100 energie-eenheden · geen verdeling bedient alle 140 gevraagde eenheden.</p>`;}
return `<p class="puzzle-help">Verplaats een deel van de rekening naar de veroorzaker. Vergelijk wie betaalt; let op wat er níét verandert.</p><label class="note-label">Aandeel afvalkosten op de rekening van NOVA: <strong id="cost-share"></strong></label><input type="range" min="0" max="100" step="25" value="${saved.share??0}" data-exp="share" aria-label="Aandeel afvalkosten bij NOVA" style="width:100%;accent-color:#648354"><div class="consequence-cards" id="consequences"></div><label class="note-label" for="prediction">Wat verwacht je dat verandert, en wat blijft gelijk?</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Voorspel wie meer betaalt en wat er gebeurt met de totale kosten.">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Voer deze afspraak uit','runExperiment')}<div id="experiment-feedback"></div><p class="experiment-caption">Rekenvoorbeeld: 100 telefoons, €100 productiekosten en €20 afvalkosten per telefoon. Het productievolume staat vast.</p>`;}
function expValues(){return Object.fromEntries([...document.querySelectorAll('[data-exp]')].map(e=>[e.dataset.exp,e.type==='checkbox'?e.checked:Number.isFinite(Number(e.value))?Number(e.value):e.value]));}
function refreshExperiment(){const b=activeBeat;if(!b||b.type!=='experiment')return;const v=expValues();if(customSimulation(b)){refreshModel(b,v);return;}state.expValues[b.id]=v;persist();if(b.simulation==='electricity'){const sum=v.production+v.repair+v.emergency;document.querySelectorAll('[data-expvalue]').forEach(e=>e.textContent=v[e.dataset.expvalue]);$('#power-meter').classList.toggle('over',sum>100);$('#power-meter i').style.width=Math.min(100,sum)+'%';$('#capacity-label').textContent=`${sum} / 100 eenheden gebruikt${sum>100?' · deze verdeling kan niet worden uitgevoerd':''}`;$('#consequences').innerHTML=[['Productie',v.production,60,v.production<60?'De lancering loopt vertraging op.':'De productielijn blijft draaien.'],['Reparatie',v.repair,40,v.repair<40?'Een deel van de reparaties wacht.':'Alle geplande reparaties gaan door.'],['Noodklanten',v.emergency,40,v.emergency<40?'Noodtoestellen worden later geleverd.':'Noodklanten ontvangen hun toestellen.']].map(([label,n,d,text])=>`<article class="consequence-card ${n<d?'waiting':''}"><strong>${label} · ${n}/${d}</strong><span>${text}</span></article>`).join('');const run=document.querySelector('[data-act=runExperiment]');if(run)run.disabled=sum>100;}else{const company=10000+2000*v.share/100,others=2000*(1-v.share/100);$('#cost-share').textContent=v.share+'%';$('#consequences').innerHTML=`<article class="consequence-card"><strong>NOVA</strong>€ ${company.toLocaleString('nl-NL')}</article><article class="consequence-card ${others?'waiting':''}"><strong>De omgeving</strong>€ ${others.toLocaleString('nl-NL')}</article><article class="consequence-card"><strong>Totale kosten</strong>€ 12.000</article>`;}}
function runExperiment(){if(customSimulation(activeBeat)){runModelTrial();return;}const b=activeBeat,v=expValues(),prediction=state.notes[`${b.id}:prediction`]?.trim();if(!prediction){notify('Noteer eerst kort wat je verwacht.');$('#prediction').focus();return;}if(b.simulation==='electricity'&&v.production+v.repair+v.emergency>100)return;state.trials[b.id]??=[];const trials=state.trials[b.id],signature=JSON.stringify(v);if(!trials.some(t=>t.signature===signature))trials.push({signature,values:v,prediction});persist();const contrast=b.simulation==='electricity'?trials.some(t=>t.values.production>=50)&&trials.some(t=>t.values.emergency>=30&&t.values.production<=30):trials.some(t=>t.values.share<=25)&&trials.some(t=>t.values.share>=75);$('#experiment-feedback').innerHTML=`<div class="small-feedback">${contrast?'Je hebt twee verschillende prioriteiten zichtbaar gemaakt. Leg nu uit wat de vergelijking laat zien.':b.simulation==='electricity'?'Probeer ook een plan dat noodklanten meer en productie minder stroom geeft, of andersom.':'Vergelijk een afspraak waarin NOVA weinig draagt met een waarin NOVA minstens 75% van de afvalkosten draagt.'}</div><p class="trial-record">${trials.length} verschillende proef${trials.length===1?'':'en'} bewaard.</p>${contrast?`<label class="note-label" for="experiment-interpretation">Welke afweging of verschuiving zie je? Wat verandert er niet vanzelf?</label><textarea id="experiment-interpretation" data-notes="${b.id}:interpretation" placeholder="Gebruik de twee proeven om het mechanisme te verklaren.">${esc(state.notes[`${b.id}:interpretation`]||'')}</textarea>${button('Bewaar mijn vergelijking','finishExperiment')}`:''}`;}
function finishExperiment(){if(customSimulation(activeBeat)){finishModel();return;}const b=activeBeat,note=state.notes[`${b.id}:interpretation`]?.trim();if(!note){notify('Beschrijf eerst de vergelijking in je eigen woorden.');return;}const question=b.simulation==='electricity'?'Wat maakte het verschil tussen je plannen?':'Wat kun je uit de twee afspraken afleiden?',options=b.simulation==='electricity'?[['criterion','Een ander verdelingscriterium verschuift wie het tekort draagt.'],['capacity','Een ander criterium verandert hoeveel stroom de accu bevat.'],['neutral','De technisch uitvoerbare verdeling bepaalt automatisch wie voorrang hoort te krijgen.']]:[['distribution','De kosten verschuiven; zonder verdere verandering blijven volume en totale kosten gelijk.'],['damage','Het verplaatsen van de rekening bewijst dat de vervuiling meteen afneemt.'],['total','NOVA betaalt meer, dus de maatschappelijke kosten zijn in dit voorbeeld hoger.']];$('#experiment-feedback').innerHTML=`<p>${question}</p><div class="puzzle-cards">${options.map(([id,text])=>`<button class="puzzle-card" data-act="interpretExperiment" data-id="${id}">${text}</button>`).join('')}</div>`;}
function interpretExperiment(id){if(customSimulation(activeBeat)){const o=conceptOptions(activeBeat).find(o=>o.id===id);if(o?.correct)collectBeat();else $('#experiment-feedback').insertAdjacentHTML('beforeend',`<div class="small-feedback retry">${esc(o?.feedback||activeBeat.hint)}</div>`);return;}const correct=activeBeat.simulation==='electricity'?'criterion':'distribution';if(id===correct)collectBeat();else $('#experiment-feedback').insertAdjacentHTML('beforeend',`<div class="small-feedback retry">${esc(activeBeat.hint)} Vergelijk wat je daadwerkelijk hebt veranderd met wat in beide proeven gelijk bleef.</div>`);}
function readClue(id){const b=allBeats().find(b=>b.id===id);selectedClue=id;tray(b.clueTitle||b.title,`<p>${esc(b.explainAfter)}</p><label class="note-label" for="clue-note">Mijn eigen verband</label><textarea id="clue-note" data-notes="${b.id}" placeholder="Aan welk ander inzicht verbind je dit?">${esc(state.notes[b.id]||'')}</textarea>${button('Terug naar de kamer','closeTray')}`,'Een bewaarde aanwijzing');}
function npcPanel(){npcTopic=null;npcFollow=null;renderNPC();}
function npcTheory(){const n=npc(),theory=n.theory;if(!theory)return;openPanel(`${n.name} legt het verband uit`,`${button('Terug naar het gesprek','npcReturn','btn-secondary')}<p class="eyebrow">${esc(n.role)} · ${esc(cfg().name)}</p><h2>${esc(theory.title)}</h2><p class="theory-concepts">${theory.concepts.map(esc).join(' · ')}</p><div class="theory-depth">${theory.sections.map((s,k)=>`<details ${k===0?'open':''}><summary>${esc(s.title)}</summary><p>${esc(s.text)}</p></details>`).join('')}</div><p class="source-note">Neem het begrip mee naar je onderzoek: welk spoor ondersteunt de uitleg, en wat moet je nog controleren?</p>${button('Het theorieoverzicht van deze les','lessonPrimer','btn-quiet')}${button('Terug naar het gesprek','npcReturn','btn-primary')}`,'Theorie, casus en verdieping');}
function openBriefing(){const b=briefings.lessons[chapter().lessonId],i=inv();openPanel(`Jouw onderzoek in ${cfg().name}`,`<div class="brief-intro"><p class="eyebrow">${esc(b.title)}</p><h2>Waar zijn we?</h2><p>${esc(b.context)}</p><div class="brief-location"><strong>Je huidige plek: ${esc(cfg().name)}</strong><p>${esc(i.world.exit.problem)}</p></div></div><details class="brief-details" open><summary>Wat probeer ik hier te ontdekken?</summary><p>${esc(b.goal)}</p><p>In deze ruimte onderzoek je ${i.beats.length} aanwijzingen. Je praat met ${npcList().map(n=>esc(n.name)).join(' en ')}, bekijkt de sporen en probeert waar nodig een ingreep uit. De volgende onderwerpen staan klaar:</p><ul>${i.beats.filter(b=>b.type!=='media').map(b=>`<li>${esc(b.title)}</li>`).join('')}</ul></details><details class="brief-details"><summary>Wanneer kan ik verder?</summary><p>Bewaar de bevindingen in je veldboek. Als alle aanwijzingen onderzocht zijn, combineer je relevant bewijs met een verklaring in de gebiedspuzzel. Een onderbouwde oplossing opent de doorgang.</p><p>${esc(i.world.exit.destinationReason)}</p><p>Je eigen voorspellingen en notities staan rechts. Je kunt je onderzoek onderbreken en later verdergaan.</p></details><div class="panel-footer">${button('Eerst snel door de theorie','lessonPrimer','btn-secondary')}${button('Ik ga onderzoeken','closePanel','btn-primary')}</div>`,'Locatie · aanleiding · opdracht');}
function welcomeArea(){state.briefed??=[];if(!state.briefed.includes(inv().id)){state.briefed.push(inv().id);persist();openBriefing();}}
function lessonPrimer(){const b=briefings.lessons[chapter().lessonId];openPanel(`Theorie vooraf · les ${state.chapter+1}`,`<p>Dit overzicht geeft je de eerste begrippen voor je onderzoek. Open wat je nodig hebt; in de kamers werk je ze verder uit met voorbeelden, gevolgen en bewijs.</p><div class="theory-primer">${b.primer.map(p=>`<details><summary>${esc(p.term)}</summary><p>${esc(p.text)}</p></details>`).join('')}</div><div class="panel-footer">${button('Mijn opdracht bekijken','openBriefing','btn-secondary')}${button('Naar de volledige oorspronkelijke uitleg','knowledge','btn-quiet')}${button('Terug naar de kamer','closePanel','btn-primary')}</div>`,'Snel overzicht · lees op je eigen tempo');}
function renderNPC(){const n=npc(),topic=n.topics.find(t=>t.id===npcTopic),follow=topic?.followups?.find(f=>f.id===npcFollow);let body=`<div class="npc-selector">${npcList().map(x=>button(esc(x.name),'switchNPC',x.name===n.name?'btn-primary':'btn-secondary',`data-name="${esc(x.name)}"`)).join('')}</div><div class="npc-line"><span class="npc-name">${esc(n.name)} · ${esc(n.role)}</span><p>${esc(follow?.answer||topic?.answer||n.opening)}</p></div>`;if(topic){body+=`<div class="npc-questions">${(topic.followups||[]).map(f=>button(esc(f.question),'npcFollow','btn-secondary',`data-id="${f.id}"`)).join('')}${button('Een andere vraag stellen','npcTopics','btn-secondary')}</div><button class="hint-toggle" data-act="saveNPC">Bewaar dit inzicht in mijn notities</button>`;}else body+=`<div class="npc-questions">${n.topics.map(t=>button(esc(t.question),'npcTopic','btn-secondary',`data-id="${t.id}"`)).join('')}</div>`;if(n.theory)body+=button('Hoe hangt dit samen met de theorie?','npcTheory','btn-primary');tray(`In gesprek met ${n.name}`,body,'Jij kiest wat je vraagt');}
function openPanel(title,body,kicker='Je onderzoek'){closeTray();panelContent.innerHTML=`<header class="panel-head"><div><p class="eyebrow">${esc(kicker)}</p><h2 id="panel-title" tabindex="-1">${esc(title)}</h2></div><button class="close" data-act="closePanel" aria-label="Sluiten">×</button></header><div class="panel-body">${body}</div>`;if(!panel.open)panel.showModal();panel.scrollTop=0;$('#panel-title').focus({preventScroll:true});}
function exitObject(){const exit=inv().world?.exit,open=state.rooms.includes(inv().id);return `<button class="scene-exit ${open?'open':'locked'}" data-act="approachExit" aria-label="${open?'Ga verder:':'Onderzoek doorgang:'} ${esc(exit?.label||'Volgende gebied')}">${icon(open?'arrow':'tool')}<span>${esc(exit?.label||'Volgende gebied')}<small>${open?'Doorgang vrij':'Een oplossing is nodig'}</small></span></button>`;}
function approachExit(){closeTray();closeInspection();walkTo(.22,.83,()=>{if(state.rooms.includes(inv().id))nextRoom();else exitPanel();});}
function exitPanel(){const e=inv().world?.exit;openPanel(e?.label||'De doorgang',`<p>${esc(e?.problem||'Onderzoek de aanwijzingen en onderbouw de oplossing voordat je verder kunt.')}</p><p>${esc(e?.destinationReason||'Je hebt het bewijs uit deze ruimte nodig in het volgende gebied.')}</p>${button('Breng de aanwijzingen samen','finale','btn-primary',investigated(state,inv())?'':'disabled')}<p class="source-note">${investigated(state,inv())?'Alle noodzakelijke aanwijzingen zijn onderzocht.':'Er zijn nog aanwijzingen te onderzoeken. Je kunt vrij rondkijken en vragen stellen.'}</p>`,'Een inhoudelijke puzzel opent de route');}
function beginKnowledge(){if(!admin.active&&!state.completedLessons.includes(chapter().lessonId))return;quizView={index:0};renderKnowledge();}
function renderKnowledge(feedback=''){const check=chapter().knowledgeCheck,q=check.items[quizView.index],key=`${chapter().lessonId}:${q.id}`,chosen=state.knowledgeAnswers[key],correct=q.options.some(o=>o.id===chosen&&o.correct);openPanel(`Les ${state.chapter+1} · kennis toepassen`,`<p class="eyebrow">Vraag ${quizView.index+1} / ${check.items.length}</p><p>${esc(check.intro)}</p><h2>${esc(q.question)}</h2><div class="puzzle-cards">${q.options.map(o=>button(esc(o.text),'knowledgeAnswer',`puzzle-card ${chosen===o.id?'selected':''}`,`data-id="${o.id}"`)).join('')}</div>${feedback?`<div class="small-feedback ${correct?'':'retry'}">${esc(feedback)}</div>`:''}${button(quizView.index===check.items.length-1?'Rond de kennischeck af':'Volgende vraag','knowledgeNext','btn-primary',correct?'':'disabled')}`,'Aanvullende vragen · verklaren in een andere situatie');}
function knowledgeAnswer(b){const q=chapter().knowledgeCheck.items[quizView.index],o=q.options.find(x=>x.id===b.dataset.id);state.knowledgeAnswers[`${chapter().lessonId}:${q.id}`]=o.id;persist();renderKnowledge(o.feedback);}
function knowledgeNext(){const check=chapter().knowledgeCheck,q=check.items[quizView.index],a=state.knowledgeAnswers[`${chapter().lessonId}:${q.id}`];if(!q.options.some(o=>o.id===a&&o.correct))return;if(quizView.index<check.items.length-1){quizView.index++;renderKnowledge();return;}if(!state.knowledgePasses.includes(chapter().lessonId))state.knowledgePasses.push(chapter().lessonId);persist();openPanel(`Les ${state.chapter+1} afgerond`, `<p>Je hebt de adventure doorlopen, het bewijs toegepast en de aanvullende vragen beantwoord. Je onderzoeksboek blijft beschikbaar.</p>${state.chapter<book.chapters.length-1?button(`Begin les ${state.chapter+2}`,'nextLesson'):button('Bekijk de volledige route','route')}${button('Bewaar mijn onderzoeksboek','export','btn-secondary')}`,'Je inzichten reizen verder');}
function nextLesson(){if(!admin.active&&(!state.completedLessons.includes(chapter().lessonId)||chapter().knowledgeCheck&&!state.knowledgePasses.includes(chapter().lessonId)))return;if(state.chapter>=book.chapters.length-1)return;state.chapter++;state.room=0;npcFocus=null;actor={x:.5,y:.85};panel.close();persist();render();speak(npc().opening);welcomeArea();}
function beginFinale(lesson=false){const current=inv();if(!lesson&&!investigated(state,current)){notify('Onderzoek eerst alle aanwijzingen.');return;}if(lesson&&chapter().investigations.some(i=>!state.rooms.includes(i.id))){notify('Rond eerst alle gebieden van deze les af.');return;}const finale=lesson?chapter().chapterFinale:current.finale;if(!finale)return;finalView={finale,key:lesson?`lesson-${state.chapter+1}`:current.id,index:0,lesson,selectedEvidence:null};renderFinale();}
function renderFinale(feedback=''){const f=finalView,{finale,index,key}=f,slot=finale.slots[index],answer=state.finalAnswers[`${key}:${slot.id}`]||{},evidence=allBeats().filter(b=>state.beats.includes(b.id)&&(f.lesson||inv().beats.includes(b))),correct=slot.options.some(o=>o.id===answer.option&&o.correct)&&answer.evidence===slot.evidenceBeatId;const facts=finale.caseFacts||finale.facts||[];openPanel(f.lesson?`De eindpuzzel van les ${state.chapter+1}`:'Breng de puzzelstukken samen.',`<section class="finale-sheet"><div class="causal-stepper">${finale.slots.map((s,n)=>`<span class="${n<index?'done':''}"></span>`).join('')}</div><p class="eyebrow">Verband ${index+1} / ${finale.slots.length} · een nieuwe situatie</p><p>${esc(finale.intro)}</p>${facts.length?`<details class="case-facts"><summary>De feiten van deze nieuwe situatie</summary>${facts.map(x=>`<p>${esc(typeof x==='string'?x:x.text||x.fact)}</p>`).join('')}</details>`:''}<h2>${esc(slot.label||slot.prompt)}</h2><div class="evidence-shelf">${evidence.map(b=>`<button class="evidence-token ${f.selectedEvidence===b.id?'selected':''}" data-act="chooseEvidence" data-id="${b.id}" data-clue="${b.id}" draggable="true">${esc(b.clueTitle||b.title)}</button>`).join('')}</div><button class="evidence-slot" data-drop-evidence="true" data-act="placeEvidence">${answer.evidence?`Bewijs: ${esc(allBeats().find(b=>b.id===answer.evidence)?.clueTitle||allBeats().find(b=>b.id===answer.evidence)?.title)}`:'Sleep hier de aanwijzing die dit verband onderbouwt, of klik eerst op een aanwijzing en dan hier.'}</button><p class="note-label">Welke verklaring volgt uit de situatie en jouw bewijs?</p><div class="puzzle-cards">${slot.options.map(o=>`<button class="puzzle-card ${answer.option===o.id?'selected':''}" data-act="finalOption" data-id="${o.id}">${esc(o.text)}</button>`).join('')}</div>${feedback?`<div class="small-feedback ${correct?'':'retry'}" aria-live="polite">${esc(feedback)}</div>`:''}<div class="panel-footer">${button('Controleer het verband','checkFinale','btn-secondary')}${button(index===finale.slots.length-1?'Maak de reconstructie af':'Volgend verband '+icon('arrow'),'nextFinal','btn-primary',correct?'':'disabled')}</div><p class="source-note">We beoordelen de verklaring en het bewijs. Over de precieze verdeling van belangen kunnen meerdere standpunten verdedigbaar zijn.</p></section>`,'Bewijsbord · kennis toepassen');}
function chooseEvidence(id){finalView.selectedEvidence=id;document.querySelectorAll('.evidence-token').forEach(e=>e.classList.toggle('selected',e.dataset.id===id));}
function placeEvidence(id=finalView.selectedEvidence){if(!id){notify('Kies eerst een gevonden aanwijzing.');return;}const f=finalView,s=f.finale.slots[f.index];state.finalAnswers[`${f.key}:${s.id}`]??={};state.finalAnswers[`${f.key}:${s.id}`].evidence=id;persist();renderFinale();}
function finalOption(id){const f=finalView,s=f.finale.slots[f.index];state.finalAnswers[`${f.key}:${s.id}`]??={};state.finalAnswers[`${f.key}:${s.id}`].option=id;persist();renderFinale();}
function checkFinal(){const f=finalView,s=f.finale.slots[f.index],a=state.finalAnswers[`${f.key}:${s.id}`]||{},o=s.options.find(o=>o.id===a.option);let feedback;if(!o)feedback='Kies een verklaring en verbind die aan een aanwijzing.';else if(a.evidence!==s.evidenceBeatId)feedback='Je verklaring moet door het juiste bewijs worden ondersteund. Kijk welk mechanisme jouw aanwijzing daadwerkelijk laat zien.';else feedback=o.feedback;renderFinale(feedback);}
function nextFinal(){const f=finalView,slot=f.finale.slots[f.index],a=state.finalAnswers[`${f.key}:${slot.id}`];if(!a||a.evidence!==slot.evidenceBeatId||!slot.options.some(o=>o.id===a.option&&o.correct))return;if(f.index<f.finale.slots.length-1){f.index++;f.selectedEvidence=null;renderFinale();return;}if(!checkFinale(state,f.finale,f.key))return;if(f.lesson){if(!state.completedLessons.includes(chapter().lessonId))state.completedLessons.push(chapter().lessonId);if(state.chapter===0)state.finalLesson=true;persist();sound();openPanel(`Les ${state.chapter+1}: verbanden gelegd.`,`<div class="room-complete"><p class="eyebrow">Nieuwe situatie onderzocht</p><h2>Pas je inzichten toe.</h2><p>${esc(f.finale.conclusion)}</p>${chapter().knowledgeCheck?button('De afsluitende vragen','beginKnowledge'):button('Bekijk mijn route','route')}${button('Bewaar mijn onderzoeksboek','export','btn-quiet')}</div>`,'De adventure en de kennischeck vullen elkaar aan');}else{try{finishRoom(state,inv());persist();sound();render();const exit=inv().world?.exit;openPanel('De doorgang is vrij.',`<div class="room-complete"><p class="eyebrow">Oplossing onderbouwd · +120 XP</p><h2>${esc(exit?.unlockedText||inv().title)}</h2><p>${esc(f.finale.conclusion)}</p><p>${esc(exit?.destinationReason||'Je neemt het gevonden bewijs mee naar het volgende gebied.')}</p>${button(lastRoom()?`Naar de eindpuzzel van les ${state.chapter+1}`:esc(exit?.label||'Naar de volgende plek'),'nextRoom')}</div>`,'Jouw verklaring maakt de volgende stap mogelijk');}catch(e){notify(e.message);}}}
function nextRoom(){if(!state.rooms.includes(inv().id))return;if(lastRoom()){beginFinale(true);return;}state.room++;npcFocus=null;actor={x:.5,y:.87};panel.close();persist();render();speak(npc().opening);welcomeArea();}
function route(){openPanel('De route door de module.',`<p>Elke les heeft meerdere gebieden. Je onderbouwde oplossing opent steeds de volgende plaats. Je gereedschap en onderzoeksboek reizen mee.</p>${book.chapters.map((ch,k)=>{const available=admin.active||k===0||state.completedLessons.includes(book.chapters[k-1].lessonId)&&(!book.chapters[k-1].knowledgeCheck||state.knowledgePasses.includes(book.chapters[k-1].lessonId));return `<section class="route-chapter"><p class="eyebrow">Les ${k+1}</p><h3>${esc(ch.title)}</h3><div class="room-map">${ch.investigations.map((i,n)=>{const open=available&&(n===0||state.rooms.includes(ch.investigations[n-1].id)),c=cfg(n,k);return `<button class="map-room" data-act="goRoom" data-chapter="${k}" data-index="${n}" ${open?'':'disabled'}><img src="${c.image}" alt=""><div><p class="eyebrow">Gebied ${n+1} / ${ch.investigations.length} · ${state.rooms.includes(i.id)?'Doorgang vrij':open?'Te onderzoeken':'Nog gesloten'}</p><h3>${esc(c.name)}</h3><p>${i.beats.length} onderzoeksmomenten</p></div></button>`;}).join('')}</div></section>`;}).join('')}${chapter().investigations.every(i=>state.rooms.includes(i.id))?button(`De eindpuzzel van les ${state.chapter+1}`,'lessonFinal'):''}${campaign.chapters.slice(book.chapters.length).map(ch=>`<div class="lesson-info">${esc(ch.title)} · wordt gebouwd</div>`).join('')}`,'Business Ethics · adventures per les');}
function blockHTML(b){if(b.t==='text')return `${b.heading?`<h3>${esc(b.heading)}</h3>`:''}${clean(b.body||'')}`;if(b.t==='tabs')return b.items.map(x=>`<article class="concept-card"><h3>${esc(x.title)}</h3>${clean(x.body)}</article>`).join('');if(b.t==='list')return `<ul>${b.items.map(x=>`<li>${clean(x)}</li>`).join('')}</ul>`;if(b.t==='svg')return `<figure><div class="diagram">${clean(b.svg)}</div><figcaption>${esc(b.caption)}</figcaption></figure>`;if(b.t==='image')return `<figure><img src="assets/course/${encodeURIComponent(b.src.split('/').at(-1))}" alt="${esc(b.caption)}" loading="lazy"><figcaption>${esc(b.caption)}</figcaption></figure>`;if(b.t==='video')return `<h3>${esc(b.title)}</h3><a href="https://www.youtube.com/watch?v=${b.youtube}${b.start?`&t=${b.start}s`:''}" target="_blank" rel="noopener">Bekijk de oorspronkelijke cursusvideo ↗</a>`;if(b.t==='quiz')return `${clean(b.question)}<details><summary>Bekijk opties en toelichting</summary>${b.options.map(o=>`<p>${o.correct?'✓ ':''}${clean(o.text)}</p>`).join('')}<p>${clean(b.feedback)}</p></details>`;if(b.t==='match')return `${clean(b.question)}<details><summary>Bekijk de verbindingen</summary>${b.pairs.map(p=>`<p><strong>${esc(p.left)}</strong><br>${esc(p.right)}</p>`).join('')}</details>`;return '';}
function knowledge(){const chapters=course.lessons.map(l=>`<details><summary>${esc(l.title)}</summary>${l.blocks.filter(b=>b.t!=='continue').map(b=>`<section class="library-block source-body">${blockHTML(b)}</section>`).join('')}</details>`).join('');openPanel('Naslag, wanneer je die nodig hebt.',`<p class="muted">De oorspronkelijke cursus blijft hier beschikbaar. Het avontuur leert je via situaties, proeven en aanwijzingen.</p><div class="library">${chapters}</div>`,'Business Ethics · volledige oorspronkelijke inhoud');}
function settings(){openPanel('Mijn onderzoek bewaren.',`<p>Je voortgang, gereedschap, proeven en notities worden op dit apparaat bewaard.</p><div class="settings-list">${button('Download voortgang en onderzoeksboek','export','btn-secondary')}${button('Beloningsgeluid: '+(state.muted?'uit':'aan'),'sound','btn-secondary')}<label class="btn btn-secondary" for="import-progress">Open een opgeslagen onderzoek<input id="import-progress" type="file" accept="application/json,.json" class="sr-only"></label>${button('Een nieuw onderzoek beginnen','resetPrompt','btn-quiet')}${button('Beheer van alle gebieden','adminPrompt','btn-secondary')}</div><p class="source-note">Vijf adventures met onderzoeken, gebiedspuzzels, eindpuzzels en afsluitende vragen. Je kunt na elke plek stoppen en later verdergaan.</p><a class="research-link" href="research.html" target="_blank" rel="noopener">Bekijk de wetenschappelijke onderbouwing en het toetsplan ↗</a><br><a class="research-link" href="plan.html" target="_blank" rel="noopener">Bekijk het volledige bouwplan ↗</a>`,'Instellingen');}
